import React from "react";

export default function MasonryGallery({ items = [] }) {
  return (
    <div className="masonry-gallery d-flex flex-wrap gap-3">
      {items.map((it, i) => (
        <div key={i} style={{ width: 200 }} className="card">
          <img
            src={it.img || "img/bg-img/default.jpg"}
            alt={it.title || ""}
            className="img-fluid"
          />
          <div className="card-body">
            <h6 className="card-title">{it.title}</h6>
          </div>
        </div>
      ))}
    </div>
  );
}
